<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import WorkspaceLayout from '../components/WorkspaceLayout.vue'
import {api,errorMessage} from '../workspace-api'
import {auth} from '../auth'
const router=useRouter(),catalog=ref({tools:[],status:'UNAVAILABLE'}),selected=ref(null),query=ref(''),error=ref(''),busy=ref(false),loading=ref(false),result=ref(null),history=ref([]),partners=ref([]),partner=ref('office'),mode=ref('form'),fields=ref({}),argumentsText=ref('{}'),pending=ref(null)
let epoch=0,controller=new AbortController(),poll
const tools=computed(()=>catalog.value.tools||[]),filtered=computed(()=>tools.value.filter(t=>(t.name+' '+t.description).toLowerCase().includes(query.value.toLowerCase())))
const schema=computed(()=>{try{return JSON.parse(selected.value?.schema||'{}')}catch{return null}})
const properties=computed(()=>Object.entries(schema.value?.properties||{})),simple=computed(()=>schema.value?.type==='object'&&properties.value.every(([,s])=>['string','boolean','number','integer'].includes(s.type)))
const statusLabel=computed(()=>({DISCOVERED:'已发现工具',UNAVAILABLE:'未发现工具',ERROR:'服务状态未取得'}[catalog.value.status]||'正在检查'))
const locked=computed(()=>busy.value||!!pending.value)
function uuid(){const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;return [...b].map((v,i)=>([4,6,8,10].includes(i)?'-':'')+v.toString(16).padStart(2,'0')).join('')}
function display(value){try{const data=JSON.parse(value);if(Array.isArray(data.content))return data.content.filter(c=>c.type==='text').map(c=>c.text).join('\n\n')||JSON.stringify(data,null,2);return JSON.stringify(data,null,2)}catch{return value||''}}
function choose(tool){selected.value=tool;result.value=null;fields.value={};pending.value=null;mode.value='form';argumentsText.value='{}';if(tool.name.endsWith('_currentTime'))fields.value.timezone='Asia/Singapore';try{if(JSON.parse(tool.schema).type!=='object')mode.value='json'}catch{mode.value='json'}}
async function refresh(){const t=epoch;loading.value=true;error.value='';try{const [c,h,p]=await Promise.all([api.get('/ai/mcp',{signal:controller.signal}),api.get('/ai/mcp/history',{signal:controller.signal}),api.get('/ai/work/catalog',{signal:controller.signal})]);if(t!==epoch)return;catalog.value=c.data;history.value=h.data;partners.value=p.data.partners;if(!partners.value.some(p=>p.id===partner.value))partner.value=partners.value[0]?.id||'';if(!selected.value&&tools.value.length)choose(tools.value.find(t=>t.name.endsWith('_currentTime'))||tools.value[0]);else if(selected.value){selected.value=tools.value.find(t=>t.name===selected.value.name)||null}}catch(e){if(t===epoch&&e.code!=='ERR_CANCELED'){error.value=errorMessage(e);catalog.value={tools:[],status:'ERROR'};selected.value=null}}finally{if(t===epoch)loading.value=false}}
function formArgs(){if(mode.value==='json'||!simple.value){const args=JSON.parse(argumentsText.value);if(!args||Array.isArray(args)||typeof args!=='object')throw Error('参数必须是 JSON 对象');return args}const args={};for(const [key,s]of properties.value){const value=fields.value[key];if(value===''||value==null){if(schema.value.required?.includes(key))throw Error('请填写必填参数：'+key);continue}if(s.type==='boolean')args[key]=value==='true'||value===true;else if(['number','integer'].includes(s.type)){const n=Number(value);if(!Number.isFinite(n)||s.type==='integer'&&!Number.isInteger(n))throw Error('请输入有效数值：'+key);args[key]=n}else args[key]=String(value)}return args}
function changeMode(){try{argumentsText.value=JSON.stringify(formArgs(),null,2);mode.value='json'}catch(e){error.value=e.message}}
async function accept(entry){result.value=entry;if(entry.status==='RUNNING'){clearTimeout(poll);const t=epoch;poll=setTimeout(async()=>{try{const r=await api.get('/ai/mcp/history/'+entry.id,{signal:controller.signal});if(t===epoch)await accept(r.data)}catch(e){if(t===epoch)error.value=errorMessage(e)}},1000)}else{pending.value=null;const t=epoch;try{const r=await api.get('/ai/mcp/history',{signal:controller.signal});if(t===epoch)history.value=r.data}catch(e){if(t===epoch)error.value=errorMessage(e)}}}
async function run(retry=false){if(busy.value||!selected.value||!retry&&pending.value)return;error.value='';let request;try{request=retry?pending.value:{name:selected.value.name,arguments:formArgs(),requestId:uuid()};if(!request)return}catch(e){error.value=e instanceof SyntaxError?'请输入合法的 JSON 参数':e.message;return}const t=epoch;busy.value=true;pending.value=request;try{const r=await api.post('/ai/mcp/call',request,{signal:controller.signal});if(t===epoch)await accept(r.data)}catch(e){if(t===epoch&&e.code!=='ERR_CANCELED'){error.value=errorMessage(e);if([400,409].includes(e.response?.status))pending.value=null;else error.value='调用状态未确认，请确认同一调用；不会自动重复执行。'}}finally{if(t===epoch)busy.value=false}}
function showRecord(entry){if(locked.value)return;const tool=tools.value.find(t=>t.name===entry.name);if(tool){choose(tool);argumentsText.value=JSON.stringify(entry.arguments,null,2);mode.value='json'}result.value=entry}
async function clearHistory(){if(locked.value||!window.confirm('清除当前账号的 MCP 手动调用记录？已经交给伙伴的附件会保留。'))return;const t=epoch;busy.value=true;try{await api.delete('/ai/mcp/history',{signal:controller.signal});if(t===epoch){history.value=[];result.value=null}}catch(e){if(t===epoch)error.value=errorMessage(e)}finally{if(t===epoch)busy.value=false}}
async function attach(){if(!result.value?.success||!partner.value)return;const t=epoch;busy.value=true;error.value='';try{const r=await api.post('/ai/mcp/history/'+result.value.id+'/attach',{partnerId:partner.value},{signal:controller.signal});if(t===epoch)await router.push({path:'/partners/'+partner.value,query:{resource:r.data.id,...(r.data.conversationId?{conversation:r.data.conversationId}:{})}})}catch(e){if(t===epoch)error.value=errorMessage(e)}finally{if(t===epoch)busy.value=false}}
watch(()=>auth.user?.id,()=>{epoch++;controller.abort();controller=new AbortController();clearTimeout(poll);selected.value=null;result.value=null;history.value=[];pending.value=null;busy.value=false;refresh()},{immediate:true})
onBeforeUnmount(()=>{epoch++;controller.abort();clearTimeout(poll)})
</script>
<template>
 <WorkspaceLayout title="MCP 工具工作台" description="发现工具、验证参数、保存调用结果，再交给工作伙伴继续处理。">
  <div v-if="error" class="error" role="alert">{{error}}</div>
  <div class="notice"><strong data-testid="mcp-status">{{statusLabel}} · {{tools.length}} 项</strong><p>{{catalog.note||'正在读取已配置服务'}}</p><small v-if="catalog.checkedAt">发现状态更新时间：{{new Date(catalog.checkedAt).toLocaleString()}} · 手动调用最长等待 {{Math.round((catalog.timeoutMs||30000)/1000)}} 秒</small></div>
  <div class="workspace-grid mcp-grid"><aside class="panel"><div class="row"><h2>工具目录</h2><button class="secondary" @click="refresh" :disabled="locked||loading">{{loading?'读取中…':'刷新'}}</button></div><input v-model="query" aria-label="搜索 MCP 工具" placeholder="搜索名称或说明"><button v-for="tool in filtered" :key="tool.name" class="item" :class="{active:selected?.name===tool.name}" :disabled="locked" @click="choose(tool)">{{tool.name.replace('yangbin_ai_agent_knowledge_','')}}<span>{{tool.description}}</span><small>{{tool.testable?'只读调用':'仅展示 · 未开放手动调用'}}</small></button><p v-if="!filtered.length&&!loading" class="muted">{{tools.length?'没有匹配的工具':'未发现工具，请检查服务配置后刷新。'}}</p><p class="muted">此页管理已由维护者配置的 MCP 服务。添加服务器或更改凭据需要部署配置，当前不支持网页安装任意服务。</p></aside>
  <div><section v-if="selected" class="panel"><h2 style="overflow-wrap:anywhere">{{selected.name}}</h2><p>{{selected.description}}</p><p class="muted">{{selected.scope}}</p><details><summary>参数定义</summary><pre>{{schema?JSON.stringify(schema,null,2):'参数定义无法解析'}}</pre></details>
   <form @submit.prevent="run(false)"><div class="row"><h3>调用参数</h3><button v-if="mode==='form'&&simple" type="button" class="secondary" @click="changeMode" :disabled="locked">切换 JSON</button></div>
    <template v-if="mode==='form'&&simple"><label v-for="[key,s] in properties" :key="key">{{key}} {{schema.required?.includes(key)?'（必填）':'（可选）'}}<small>{{s.description}}</small><select v-if="s.enum||s.type==='boolean'" v-model="fields[key]" :aria-label="key" :disabled="locked"><option value="">请选择</option><option v-for="choice in s.enum||['true','false']" :key="String(choice)" :value="String(choice)">{{choice}}</option></select><input v-else v-model="fields[key]" :aria-label="key" :type="['integer','number'].includes(s.type)?'number':'text'" :step="s.type==='integer'?1:'any'" :maxlength="Math.min(s.maxLength||8000,8000)" :disabled="locked" :placeholder="key==='filename'?'先运行 listKnowledgeDocuments 获取准确文件名':''"></label><p v-if="!properties.length" class="muted">此工具无需参数。</p></template>
    <label v-else>调用参数（JSON）<textarea v-model="argumentsText" aria-label="调用参数 JSON" spellcheck="false" :disabled="locked"></textarea></label>
    <button type="submit" :disabled="locked||!selected.testable||!schema||catalog.status!=='DISCOVERED'">{{busy?'调用中…':'运行工具'}}</button>
   </form>
   <button v-if="pending&&!busy" class="secondary" @click="run(true)">确认同一调用</button>
  </section>
  <section v-if="result" class="panel" aria-label="MCP 调用结果"><div class="row"><h2>调用结果</h2><span class="badge" :class="{failed:!result.success}" data-testid="mcp-result-status">{{result.status|| (result.success?'SUCCEEDED':'FAILED')}}</span><span>{{result.durationMs}} ms</span></div><p class="muted">{{result.name}} · {{new Date(result.time).toLocaleString()}}</p><p v-if="result.truncated" class="notice">结果超出保存长度，已截断；交给伙伴时也仅包含当前内容。</p><pre data-testid="mcp-result">{{display(result.result)}}</pre><a class="secondary" :href="'/api/ai/mcp/history/'+result.id+'/download'" :download="'mcp-'+result.id+'.md'">下载结果与来源</a><div v-if="result.success" class="mcp-handoff"><label>交给工作伙伴<select v-model="partner" aria-label="接收 MCP 结果的伙伴" :disabled="locked"><option v-for="p in partners" :key="p.id" :value="p.id">{{p.name}}</option></select></label><button @click="attach" :disabled="locked||!partner">引用到伙伴</button><p class="muted">保存为当前账号的附件；进入伙伴后确认需求再发送，不会自动调用模型。</p></div></section>
  <section class="panel"><div class="row"><h2>调用历史</h2><button class="secondary" @click="clearHistory" :disabled="locked||!history.length">清空历史</button></div><p class="muted">按账号保存最近 50 条手动记录，重启后可恢复；聊天中的自动调用仍在聊天页查看。</p><button v-for="item in history" :key="item.id" class="item" :disabled="locked" @click="showRecord(item)">{{item.success?'成功':item.status}} · {{item.name}}<span>{{new Date(item.time).toLocaleString()}} · {{item.durationMs}} ms</span></button><p v-if="!history.length" class="muted">还没有调用记录。</p></section></div></div>
 </WorkspaceLayout>
</template>
<style scoped>
.mcp-grid input,.mcp-grid select{box-sizing:border-box;width:100%;padding:10px;border:1px solid #dce3ef;border-radius:8px;background:white;color:#304260}.mcp-grid label{display:block;margin:14px 0}.mcp-grid label small{display:block;margin:6px 0;color:#7b879a}.mcp-grid pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:420px;overflow:auto}.mcp-grid textarea{font-family:monospace;min-height:140px}.mcp-grid .item{overflow-wrap:anywhere}.mcp-grid .item small{display:block;margin-top:6px;font-size:11px;color:#658877}.mcp-handoff{border-top:1px solid #e6ebf3;margin-top:20px;padding-top:10px}.mcp-grid h2{overflow-wrap:anywhere}.mcp-grid .row{flex-wrap:wrap}.notice p{margin:7px 0}.mcp-grid a.secondary{display:inline-block;margin-top:10px}@media(max-width:760px){.mcp-grid{grid-template-columns:1fr}.mcp-grid h2{font-size:17px}}
</style>
